'use client'
import React, { useEffect, useRef, useState } from 'react'
import { Card } from '@/components/ui/card'

export function ReactionPlay({ state, onSubmit }: { state: { rounds: number; delaysMs: number[] }; onSubmit: (answer: unknown) => void }) {
  const [round, setRound] = useState(0)
  const [phase, setPhase] = useState<'waiting' | 'go' | 'tooSoon'>('waiting')
  const [times, setTimes] = useState<(number | null)[]>([])
  const goAt = useRef<number>(0)
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null)

  useEffect(() => {
    if (round >= state.rounds) {
      onSubmit({ reactionTimesMs: times })
      return
    }
    setPhase('waiting')
    timer.current = setTimeout(() => {
      goAt.current = performance.now()
      setPhase('go')
    }, state.delaysMs[round])
    return () => {
      if (timer.current) clearTimeout(timer.current)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [round])

  const tap = () => {
    if (phase === 'waiting') {
      if (timer.current) clearTimeout(timer.current)
      setPhase('tooSoon')
      setTimes((t) => [...t, null])
      setTimeout(() => setRound((r) => r + 1), 700)
      return
    }
    if (phase === 'go') {
      const rt = Math.round(performance.now() - goAt.current)
      setTimes((t) => [...t, rt])
      setRound((r) => r + 1)
    }
  }

  return (
    <Card className="overflow-hidden border-[#F5B82E]/20 bg-[#0B111A] p-0">
      <div className="px-5 pt-5">
        <p className="text-[12px] font-medium uppercase tracking-[0.12em] text-[#F5B82E]">Round {Math.min(round + 1, state.rounds)} of {state.rounds}</p>
      </div>
      <button
        onClick={tap}
        className={`mt-4 flex h-64 w-full flex-col items-center justify-center transition-colors ${
          phase === 'go' ? 'bg-[#2F6F4E] text-white' : phase === 'tooSoon' ? 'bg-[#C1503A] text-white' : 'bg-[#101a2a] text-slate-100'
        }`}
      >
        <p className="font-display text-[22px]">
          {phase === 'go' ? 'Tap now!' : phase === 'tooSoon' ? 'Too soon' : 'Wait for it…'}
        </p>
      </button>
    </Card>
  )
}

import { APIError } from 'payload'
import { isAppError } from '@/lib/errors'

/** Run a service call inside a Payload hook and surface AppErrors as admin-friendly APIErrors. */
export async function asApiError<T>(fn: () => Promise<T>): Promise<T> {
  try {
    return await fn()
  } catch (err) {
    if (isAppError(err)) throw new APIError(err.message, err.status)
    throw err
  }
}

'use client'

export class ApiError extends Error {
  code: string
  status: number
  details?: Record<string, unknown>
  constructor(code: string, message: string, status: number, details?: Record<string, unknown>) {
    super(message)
    this.code = code
    this.status = status
    this.details = details
  }
}

function buildUrl(path: string, params?: Record<string, string | number | boolean | null | undefined>) {
  const cleanPath = path.startsWith('/api') ? path : `/api${path.startsWith('/') ? path : `/${path}`}`
  if (!params) return cleanPath

  const search = new URLSearchParams()
  for (const [key, value] of Object.entries(params)) {
    if (value == null) continue
    search.append(key, String(value))
  }

  const qs = search.toString()
  return qs ? `${cleanPath}${cleanPath.includes('?') ? '&' : '?'}${qs}` : cleanPath
}

async function request<T>(path: string, init?: RequestInit, params?: Record<string, string | number | boolean | null | undefined>): Promise<T> {
  const url = buildUrl(path, params)
  const res = await fetch(url, {
    ...init,
    headers: { 'Content-Type': 'application/json', ...(init?.headers ?? {}) },
    credentials: 'include',
    cache: 'no-store',
  })
  const json = await res.json().catch(() => null)
  if (!res.ok || !json?.ok) {
    const err = json?.error ?? { code: 'INTERNAL', message: 'Something went wrong. Please try again.' }
    throw new ApiError(err.code, err.message, res.status, err.details)
  }
  return json.data as T
}

export const api = {
  get: <T>(path: string, params?: Record<string, string | number | boolean | null | undefined>) => request<T>(path, { method: 'GET' }, params),
  post: <T>(path: string, body?: unknown) => request<T>(path, { method: 'POST', body: body ? JSON.stringify(body) : undefined }),
  del: <T>(path: string) => request<T>(path, { method: 'DELETE' }),
}

/**
 * Recomputes every wallet balance from its source of truth (the ledger + withdrawals) and reports any
 * mismatch. Run on a schedule (e.g. nightly) as a correctness safety net:  npm run reconcile
 */
import 'dotenv/config'
import { getPayloadClient } from '../src/lib/payload'
import { reconcileWallets } from '../src/services/wallet'
import { logAudit } from '../src/services/audit'

async function main() {
  const payload = await getPayloadClient()
  const { checked, mismatches } = await reconcileWallets(payload)
  console.log(`Checked ${checked} wallets.`)
  if (mismatches.length === 0) {
    console.log('No mismatches found. ✅')
  } else {
    console.error(`Found ${mismatches.length} mismatch(es):`)
    for (const m of mismatches) console.error(`  wallet #${m.walletId} (user #${m.userId}) ${m.field}: stored=${m.stored} expected=${m.expected}`)
    await logAudit({ payload, action: 'WALLET_RECONCILED', actorLabel: 'system:reconcile-script', metadata: { checked, mismatches } })
  }
  process.exit(mismatches.length ? 1 : 0)
}

main().catch((err) => {
  console.error(err)
  process.exit(1)
})

